package com.akitaattribute.mobfarmblock.behavior;
import com.akitaattribute.mobfarmblock.mob.*; import net.minecraft.block.entity.BlockEntity; import net.minecraft.entity.ExperienceOrbEntity; import net.minecraft.inventory.Inventory; import net.minecraft.item.*; import net.minecraft.registry.Registries; import net.minecraft.server.world.ServerWorld; import net.minecraft.util.ItemScatterer; import net.minecraft.util.math.Direction;
final class BehaviorUtil { static void give(PlayerEntityAccess p, ItemStack s){} private BehaviorUtil(){} static void output(MobFarmContext c, ItemStack stack){ if(stack.isEmpty())return; BlockEntity be=c.level().getBlockEntity(c.pos().down()); if(be instanceof Inventory inv){ for(int i=0;i<inv.size()&&!stack.isEmpty();i++) stack=ItemStackUtil.insert(inv,stack,i);} if(!stack.isEmpty()) ItemScatterer.spawn(c.level(), c.pos().getX()+.5, c.pos().getY()+1, c.pos().getZ()+.5, stack); }
 static AttackResult attack(MobFarmContext c){var s=c.stored(); if(s.isEmpty())return AttackResult.PASS; s.count--; for(DropRule r:s.dropProfile.drops()){ if(c.random().nextDouble()<=r.chance()){int n=r.minCount()+c.random().nextInt(Math.max(1,r.maxCount()-r.minCount()+1)); output(c,new ItemStack(Registries.ITEM.get(r.itemId()),n));}} XpProfile xp=s.dropProfile.xp(); if(xp.maxXp()>0 && c.level() instanceof ServerWorld sw){int amount=xp.minXp()+c.random().nextInt(Math.max(1,xp.maxXp()-xp.minXp()+1)); ExperienceOrbEntity.spawn(sw,c.pos().toCenterPos(),amount);} return AttackResult.SUCCESS; } }
class ItemStackUtil{static ItemStack insert(Inventory inv,ItemStack stack,int slot){var cur=inv.getStack(slot); if(cur.isEmpty()){inv.setStack(slot,stack.copy()); return ItemStack.EMPTY;} if(ItemStack.areItemsAndComponentsEqual(cur,stack)&&cur.getCount()<cur.getMaxCount()){int move=Math.min(stack.getCount(),cur.getMaxCount()-cur.getCount());cur.increment(move);stack.decrement(move);} return stack;}}
interface PlayerEntityAccess{}
